/**
 * ASHBLADE - Kael directional sprite adapter (Option D, Soul Knight 3-Facing).
 *
 * No frame guessing, background segmentation, or image recognition at runtime.
 * Reads three exact RGBA atlases generated by tools/build_atlases.py.
 * Gameplay physics, collisions, damage and VFX still belong to the existing game.
 */
import { SS } from './gfx.js';

const CELL_W = 128;
const CELL_H = 96;
const COLS = 10;
const ROWS = Object.freeze({
  entrance: 0, idle: 1, walk: 2, run: 3,
  attack1: 4, attack2: 5, attack3: 6,
  skill1: 7, skill2: 8, ultimate: 9,
  dash: 10, hit: 11, death: 12,
});
const COUNTS = Object.freeze({
  entrance: 8, idle: 8, walk: 8, run: 8,
  attack1: 8, attack2: 8, attack3: 8,
  skill1: 8, skill2: 8, ultimate: 10,
  dash: 6, hit: 4, death: 8,
});
let loadGeneration = 0;
const cache = new Map();
const urlFor = (direction) => new URL(`../art/sprites/kael-master/kael-${direction}.png?v=401`, import.meta.url).href;

function loadImage(url) {
  if (cache.has(url)) return cache.get(url);
  const task = new Promise((resolve, reject) => {
    const img = new Image();
    img.decoding = 'async';
    img.onload = () => {
      if (img.naturalWidth !== CELL_W * COLS || img.naturalHeight !== CELL_H * Object.keys(ROWS).length) {
        reject(new Error(`Kael atlas dimensions invalid: ${img.naturalWidth}x${img.naturalHeight}: ${url}`));
      } else resolve(img);
    };
    img.onerror = () => reject(new Error(`Cannot load Kael sprite atlas ${url}`));
    img.src = url;
  });
  cache.set(url, task);
  return task;
}

function newCanvas(w, h) {
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  canvas.getContext('2d').imageSmoothingEnabled = false;
  return canvas;
}

/** Exact render contract expected by src/gfx.js: {n,f,w,h,k,tint}. */
function frameSprite(img, col, row) {
  const n = newCanvas(CELL_W, CELL_H);
  const g = n.getContext('2d');
  g.drawImage(img, col * CELL_W, row * CELL_H, CELL_W, CELL_H, 0, 0, CELL_W, CELL_H);
  const f = newCanvas(CELL_W, CELL_H);
  const fg = f.getContext('2d');
  fg.translate(CELL_W, 0); fg.scale(-1, 1); fg.drawImage(n, 0, 0);
  const tinted = new Map();
  return {
    n, f, k: SS, w: CELL_W / SS, h: CELL_H / SS,
    tint(color, flipped = false) {
      const key = `${color}:${flipped}`;
      if (tinted.has(key)) return tinted.get(key);
      const t = newCanvas(CELL_W, CELL_H), tg = t.getContext('2d');
      tg.drawImage(flipped ? f : n, 0, 0);
      tg.globalCompositeOperation = 'source-in';
      tg.fillStyle = color; tg.fillRect(0, 0, CELL_W, CELL_H);
      if (tinted.size > 5) tinted.clear();
      tinted.set(key, t);
      return t;
    },
  };
}

function createDirection(img) {
  const frames = {};
  for (const [action, row] of Object.entries(ROWS)) {
    frames[action] = Array.from({ length: COUNTS[action] }, (_, i) => frameSprite(img, i, row));
  }
  return {
    idle: frames.idle[0], idles: frames.idle,
    walk: frames.walk, run: frames.run,
    art: true, noWeapon: true, ownWeapon: true,
    // Existing game expects an eye position even though art=true disables its eye glow.
    eye: [CELL_W / SS / 2, 15],
    act: {
      stance: frames.idle[0],
      entrance: frames.entrance,
      attack: [frames.attack1, frames.attack2, frames.attack3],
      attack1: frames.attack1,
      attack2: frames.attack2,
      attack3: frames.attack3,
      charge: frames.attack1[0],
      release: frames.attack3,
      skill: frames.skill1, skill1: frames.skill1,
      skill2: frames.skill2, ultimate: frames.ultimate,
      dash: frames.dash, hit: frames.hit, death: frames.death,
    },
  };
}

/** Non-blocking: the old Kael remains visible until the atlas is fully loaded. */
export function installKaelVisuals(SPR) {
  const myGeneration = ++loadGeneration;
  Promise.all(['right', 'center'].map((dir) => loadImage(urlFor(dir)))).then((imgs) => {
    if (myGeneration !== loadGeneration) return; // theme rebuild was newer
    const directions = {
      right: createDirection(imgs[0]),
      center: createDirection(imgs[1]),
    };
    directions.center.directions = directions;
    // Only replace BASE Kael. Evolved artwork keeps its original look.
    SPR.chars.BLADE = directions.center;
    SPR.kaelVisualReady = true;
    console.info('[ASHBLADE] Kael visual master loaded: center/right + mirrored left');
  }).catch((err) => console.error('[ASHBLADE] Kael atlas load failed; legacy sprite retained', err));
}
